using System;using System.Data.SqlClient;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class NotificationsPage:UserControl{DataGridView grid;public NotificationsPage(){grid=Ui.Grid();Controls.Add(grid);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=50};var read=Ui.Button(L.Fa?"خوانده شد":"Mark read",false);read.Click+=(s,e)=>Mark();bar.Controls.Add(read);Controls.Add(bar);bar.BringToFront();LoadData();}void LoadData(){grid.DataSource=Database.Query("SELECT Id,Title,Message,IsRead,CreatedAt FROM Notifications WHERE UserId IS NULL OR UserId=@u ORDER BY CreatedAt DESC",new SqlParameter("@u",AppSession.UserId));}void Mark(){if(grid.CurrentRow==null)return;Database.Exec("UPDATE Notifications SET IsRead=1 WHERE Id=@id",new SqlParameter("@id",grid.CurrentRow.Cells["Id"].Value));LoadData();}}}